<?php require_once 'includes/config.php'; require_login(); $pdo=db(); $u=user(); if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='profile'){$name=trim(post_str('name'));$phone=trim(post_str('phone'));if($name===''||strlen($name)>120){flash('danger','Enter a valid name.');}else{$st=$pdo->prepare('UPDATE users SET name=?,phone=? WHERE id=? AND role=\'customer\'');$st->execute([$name,$phone,$u['id']]);$_SESSION['user']['name']=$name;flash('success','Profile updated.');}}elseif($action==='password'){$st=$pdo->prepare('SELECT password FROM users WHERE id=?');$st->execute([$u['id']]);$row=$st->fetch();if(!password_verify($_POST['current']??'',$row['password']))flash('danger','Current password is incorrect.');elseif(strlen($_POST['new']??'')<8)flash('danger','New password must be at least 8 characters.');else{$st=$pdo->prepare('UPDATE users SET password=? WHERE id=?');$st->execute([password_hash($_POST['new'],PASSWORD_DEFAULT),$u['id']]);flash('success','Password changed.');}}elseif($action==='address'){$st=$pdo->prepare('INSERT INTO addresses(user_id,label,line1,city,state,pincode,phone,is_default) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$u['id'],post_str('label'),post_str('line1'),post_str('city'),post_str('state'),post_str('pincode'),post_str('phone'),0]);flash('success','Address saved.');}elseif($action==='delete_address'){$st=$pdo->prepare('DELETE FROM addresses WHERE id=? AND user_id=?');$st->execute([(int)$_POST['id'],$u['id']]);flash('success','Address removed.');}elseif($action==='delete_account'){$st=$pdo->prepare('SELECT password,role FROM users WHERE id=?');$st->execute([$u['id']]);$check=$st->fetch();if(!$check||$check['role']!=='customer'||!password_verify((string)($_POST['current_password']??''),$check['password'])){flash('danger','Password incorrect. Account was not deleted.');}else{$pdo->beginTransaction();try{$id=(int)$u['id'];$pdo->prepare('DELETE FROM addresses WHERE user_id=?')->execute([$id]);$pdo->prepare('DELETE FROM wishlists WHERE user_id=?')->execute([$id]);$pdo->prepare('DELETE FROM reviews WHERE user_id=?')->execute([$id]);$pdo->prepare('DELETE FROM notifications WHERE user_id=?')->execute([$id]);$pdo->prepare('DELETE FROM support_tickets WHERE user_id=?')->execute([$id]);// Preserve order history while anonymizing and disabling the customer's account.
$deletedEmail = 'deleted+' . $id . '@account.invalid';
$disabledPassword = password_hash(bin2hex(random_bytes(32)), PASSWORD_DEFAULT);
$pdo->prepare("UPDATE users SET name='Deleted customer', email=?, phone=NULL, password=?, status=0 WHERE id=? AND role='customer'")
    ->execute([$deletedEmail, $disabledPassword, $id]);
$pdo->commit();$_SESSION=[];session_destroy();redirect('index.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Could not delete account because related order or payment records must be retained. Contact support for assistance.');}}}redirect('account.php');}$st=$pdo->prepare('SELECT * FROM users WHERE id=?');$st->execute([$u['id']]);$me=$st->fetch();$st=$pdo->prepare('SELECT * FROM addresses WHERE user_id=? ORDER BY is_default DESC,id DESC');$st->execute([$u['id']]);$addresses=$st->fetchAll();$title='My Account';require 'includes/header.php'; ?><div class="row g-4"><aside class="col-lg-3"><div class="list-group account-nav"><a class="list-group-item list-group-item-action active">My Account</a><a class="list-group-item list-group-item-action" href="orders.php">My Orders</a><a class="list-group-item list-group-item-action" href="wishlist.php">Wishlist</a><a class="list-group-item list-group-item-action" href="support.php">Support</a></div></aside><section class="col-lg-9"><h1 class="section-title">Account settings</h1><div class="row g-4"><div class="col-md-6"><div class="panel p-4"><h5>Profile</h5><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="profile"><label class="form-label">Full name</label><input class="form-control mb-3" name="name" value="<?=e($me['name'])?>" required><label class="form-label">Email</label><input class="form-control mb-3" value="<?=e($me['email'])?>" disabled><label class="form-label">Phone</label><input class="form-control mb-3" name="phone" value="<?=e($me['phone'])?>"><button class="btn btn-purple">Save Profile</button></form></div></div><div class="col-md-6"><div class="panel p-4"><h5>Security</h5><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="password"><input class="form-control mb-2" name="current" type="password" placeholder="Current password" required><input class="form-control mb-3" name="new" type="password" minlength="8" placeholder="New password" required><button class="btn btn-outline-purple">Change Password</button></form></div></div><div class="col-12"><div class="panel p-4"><div class="d-flex justify-content-between"><h5>Saved addresses</h5><button class="btn btn-sm btn-purple" data-bs-toggle="modal" data-bs-target="#addr">Add address</button></div><?php foreach($addresses as $a):?><div class="border rounded-3 p-3 mt-3 d-flex justify-content-between"><div><strong><?=e($a['label'])?></strong><div class="text-secondary"><?=e($a['line1'])?>, <?=e($a['city'])?>, <?=e($a['state'])?> - <?=e($a['pincode'])?></div></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete_address"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Remove this address?">Remove</button></form></div><?php endforeach;?><?php if(!$addresses):?><p class="text-secondary mt-3">No saved addresses yet.</p><?php endif;?></div></div></div><div class="col-12"><div class="panel p-4 border-danger"><h5 class="text-danger">Delete account</h5><p class="text-secondary">Permanently delete your customer profile and saved addresses. Orders may require support-assisted handling for accounting and order-history reasons.</p><button class="btn btn-outline-danger" data-bs-toggle="modal" data-bs-target="#deleteAccount">Delete my account</button></div></div></section></div><div class="modal fade" id="deleteAccount"><div class="modal-dialog"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete_account"><div class="modal-header"><h5 class="text-danger">Confirm account deletion</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p>This action cannot be undone. Confirm your current password to continue.</p><input class="form-control" type="password" name="current_password" autocomplete="current-password" required placeholder="Current password"></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger">Permanently delete account</button></div></form></div></div></div><div class="modal fade" id="addr"><div class="modal-dialog"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="address"><div class="modal-header"><h5>Add address</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input class="form-control mb-2" name="label" placeholder="Home / Work" required><input class="form-control mb-2" name="line1" placeholder="Address line" required><div class="row g-2"><div class="col"><input class="form-control" name="city" placeholder="City" required></div><div class="col"><input class="form-control" name="state" placeholder="State" required></div></div><div class="row g-2 mt-1"><div class="col"><input class="form-control" name="pincode" placeholder="Pincode" required></div><div class="col"><input class="form-control" name="phone" placeholder="Phone"></div></div></div><div class="modal-footer"><button class="btn btn-purple">Save Address</button></div></form></div></div></div><?php require 'includes/footer.php'; ?>